"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["54136"],{74974(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.etapa_nota_enem_sem_classificacao_enem","status":422,"titulo":"Etapa de nota do ENEM exige classifica\xe7\xe3o baseada em ENEM pela m\xe9dia ponderada"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.etapa_nota_enem_sem_classificacao_enem","requisitos":[],"oQueAconteceu":["O processo tem uma etapa cuja nota vem do ENEM, mas a classifica\xe7\xe3o declarada n\xe3o \xe9\\nbaseada em ENEM ou n\xe3o \xe9 calculada pela m\xe9dia ponderada, que \xe9 a f\xf3rmula em que a nota\\ndo ENEM entra como componente. A mensagem de detalhe cita a etapa. A recusa sai com\\n**422** e nada foi gravado.","A confer\xeancia acontece nos dois sentidos: ao definir as etapas, contra a classifica\xe7\xe3o\\nque j\xe1 est\xe1 gravada, e ao definir a classifica\xe7\xe3o, contra as etapas que j\xe1 existem. Se\\na classifica\xe7\xe3o ainda n\xe3o foi gravada, a defini\xe7\xe3o das etapas n\xe3o \xe9 recusada por este\\nmotivo. Quando a recusa vem da defini\xe7\xe3o da classifica\xe7\xe3o, o erro aponta os campos da\\nclassifica\xe7\xe3o que impedem o c\xe1lculo local do ENEM."],"comoResolver":["Escolha o ajuste que reflete o edital:","- declare a classifica\xe7\xe3o baseada em ENEM, calculada pela m\xe9dia ponderada\\n  (`PUT /api/selecao/processos-seletivos/{id}/classificacao`); ou\\n- retire do processo a etapa com nota do ENEM\\n  (`PUT /api/selecao/processos-seletivos/{id}/etapas`)."],"ondeAparece":["Defini\xe7\xe3o de etapas do processo seletivo","Defini\xe7\xe3o de classifica\xe7\xe3o do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);